def low_stock(items):
    """Return alphabetically sorted names of items below the low-stock threshold."""
    threshold = int(app.settings.get("LOW_STOCK_THRESHOLD", 12))
    return sorted(item["name"] for item in items if item["quantity"] < threshold)

